package ma.fstt.model;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="commande") public class Commande { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private LocalDateTime dateCommande; private String statut; @ManyToOne(optional=false) @JoinColumn(name="client_id") private Client client; @OneToMany(mappedBy="commande",cascade=CascadeType.ALL,orphanRemoval=true) private List<LigneCommande> lignes=new ArrayList<>(); public Commande(){} public Commande(Client c){client=c;dateCommande=LocalDateTime.now();statut="VALIDEE";} public void ajouterLigne(LigneCommande l){lignes.add(l);l.setCommande(this);} public Long getId(){return id;} public LocalDateTime getDateCommande(){return dateCommande;} public String getStatut(){return statut;} public Client getClient(){return client;} public List<LigneCommande> getLignes(){return lignes;} }